create table if not exists public.payment_transactions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, reference text not null unique, plan_code text not null check (plan_code in ('silver_daily','gold_weekly','diamond_monthly','platinum_yearly')), amount_kobo integer not null check (amount_kobo > 0), currency text not null default 'NGN' check (currency = 'NGN'), coins_to_credit integer not null default 0 check (coins_to_credit >= 0), membership_days integer not null default 0 check (membership_days >= 0), status text not null default 'pending' check (status in ('pending','paid','failed')), paystack_transaction_id text unique, created_at timestamptz not null default now(), paid_at timestamptz, metadata jsonb not null default '{}'::jsonb); create index if not exists payment_transactions_user_created_idx on public.payment_transactions(user_id, created_at desc); create table if not exists public.user_subscriptions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, plan_code text not null check (plan_code in ('gold_weekly','diamond_monthly','platinum_yearly')), status text not null default 'active' check (status in ('active','superseded','expired')), started_at timestamptz not null default now(), expires_at timestamptz not null, updated_at timestamptz not null default now()); create index if not exists user_subscriptions_user_status_expiry_idx on public.user_subscriptions(user_id,status,expires_at desc); create table if not exists public.coin_ledger (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, transaction_reference text not null unique, amount integer not null, reason text not null, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now()); create index if not exists coin_ledger_user_created_idx on public.coin_ledger(user_id,created_at desc); alter table public.payment_transactions enable row level security; alter table public.user_subscriptions enable row level security; alter table public.coin_ledger enable row level security; create policy "members read own payment transactions" on public.payment_transactions for select to authenticated using (auth.uid()=user_id); create policy "members read own subscriptions" on public.user_subscriptions for select to authenticated using (auth.uid()=user_id); create policy "members read own coin ledger" on public.coin_ledger for select to authenticated using (auth.uid()=user_id); grant select on public.payment_transactions,public.user_subscriptions,public.coin_ledger to authenticated;